import { getEnvironmentVariableByName } from '../api/control-plane.js';
import * as log from './log.js';
export const PAYLOAD_SECRET_ENV_VAR = 'PAYLOAD_SECRET';
/**
 * Resolve the tenant's PAYLOAD_SECRET and cache it in the encrypted
 * TokenStore. The secret is intentionally NOT written to `.env`: keeping it
 * only in the machine-scoped, AES-256-GCM-encrypted store avoids the
 * plaintext-on-disk / accidental-exfiltration risks of a project-local file.
 * `buildFigmaConfig` reads it back from the TokenStore at dev/build time.
 *
 * The Figma platform owns PAYLOAD_SECRET rotation; this helper never
 * generates or mutates the value — it only fetches whatever the Control
 * Plane currently returns and caches it.
 *
 * Non-fatal on failure: callers should catch and log rather than abort init,
 * so the sinatra endpoint rollout can lag the CLI.
 */ export async function ensurePayloadSecret({ credential, projectInfo, refresh = false, tenantInstanceId, tokenStore }) {
    const cached = tokenStore.getPayloadSecret({
        projectInfo
    });
    if (cached && !refresh) {
        return cached;
    }
    const secret = await getEnvironmentVariableByName(credential, tenantInstanceId, PAYLOAD_SECRET_ENV_VAR);
    if (!secret) {
        throw new Error('Control Plane returned an empty PAYLOAD_SECRET');
    }
    tokenStore.setPayloadSecret({
        projectInfo,
        secret
    });
    log.debug(`Cached PAYLOAD_SECRET for ${projectInfo.projectId}:${projectInfo.environmentName}`);
    return secret;
}
